const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const body = ($('Приём документа').item.json.body) || {};
let mime = body.mime_type || ($input.item.binary && $input.item.binary.data && $input.item.binary.data.mimeType) || 'image/jpeg';
return { json: { file_base64: base64, file_mime: mime, doc_id: body.doc_id || null } };

const doc = ($('Приём документа').item.json.body) || {};
const resp = $json;
let text = '';
try { text = resp.candidates[0].content.parts[0].text; } catch (e) {}
let data = {};
try { data = JSON.parse(text); } catch (e) { data = { recognized: false, reason: 'Модель вернула нечитаемый ответ' }; }

const isFinancial = data.is_financial_document !== false;
const amountOk = data.amount !== undefined && data.amount !== null && String(data.amount).trim() !== '';

let ok = false;
let autoExcluded = false;
let reason = null;

if (!isFinancial) {
  ok = true;
  autoExcluded = true;
  reason = data.reason || 'Не финансовый документ (например, приказ или распоряжение) — сумма к оплате не применима, документ автоматически исключён из сметы';
} else {
  ok = data.recognized === true && !!data.doc_number && !!data.doc_date && amountOk;
  reason = ok ? null : (data.reason || 'Ключевые поля не читаются');
}

return { json: {
  doc_id: doc.doc_id || null,
  recognized: ok,
  auto_excluded: autoExcluded,
  confidence: (data.confidence != null ? data.confidence : null),
  fields: {
    doc_type: data.doc_type || null,
    supplier: data.supplier || null,
    doc_number: data.doc_number || null,
    doc_date: data.doc_date || null,
    amount: (data.amount != null ? data.amount : null),
    vat: (data.vat != null ? data.vat : null)
  },
  reason: reason,
  model: 'gemini-2.5-flash'
} };
